package com.spai.portal.organization.controller;import java.util.*;import com.spai.portal.common.ApiResponse;import com.spai.portal.organization.domain.*;import com.spai.portal.organization.repository.*;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;@RestController @RequestMapping("/api/v1/admin")@PreAuthorize("hasRole('ADMIN')")public class OrganizationController{private final AppUserRepository users;private final TeamRepository teams;public OrganizationController(AppUserRepository users,TeamRepository teams){this.users=users;this.teams=teams;}@GetMapping("/users")public ApiResponse<List<AppUser>>users(){return ApiResponse.ok(users.findAll());}@GetMapping("/teams")public ApiResponse<List<Team>>teams(){return ApiResponse.ok(teams.findAll());}}
